bad_example.code:
// Write code
function discount(user, order) {
  if (user.vip && order.total > 1000) return 0.20;
  if (order.total > 2000) return 0.05;
  return 0;
}

// Later (or never): write tests
// But by then, untestable dependencies exist
// Can't test without complex setup

good_example.code:
// First: Write failing test
test('discount for VIP over 1000 is 20%', () => {
  const user = { vip: true };
  const order = { total: 1500 };
  expect(discount(user, order)).toBe(0.20);
});

// Second: Write minimum code to pass
function discount(user, order) {
  if (user.vip && order.total > 1000) return 0.20;
  return 0;
}

// Third: Refactor both test and code
// Now add next test, repeat

bad_example.code:
// Obviously wrong but everyone's afraid to change it
class OrderProcessor {
  function process(order) {
    // Embedded SQL, no tests, no structure
    // Everyone says 'it works, don't touch it'
    // Improvements are never made
  }
}

good_example.code:
// Code is now safe to change
test('OrderProcessor handles valid order', () => {
  // Test ensures code behavior
});

class OrderProcessor {
  // Developers now confident to refactor
  // Each improvement is verified by tests
  // Code improves over time
}

