good_example.code:
// RED: Test fails
test('discount logic', () => { ... });

// GREEN: Minimum code
function discount(u, o) {
  if (u.v && o.t > 100) return 0.1;
  return 0;
}

// REFACTOR: Make it clear
function discount(user, order) {
  if (isVipCustomer(user) && isLargeOrder(order)) {
    return VIP_DISCOUNT;
  }
  return NO_DISCOUNT;
}

